
@use './面板样式.scss';

.zx-dim {
  color: var(--zx-墨淡);
  font-size: 11.5px;
}

/* 在家时：四个能去的地方，点一下就把正文带过去。 */
.zx-go {
  padding-bottom: 2px;
}

.zx-go-row {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 8px;
  margin: 10px 0 10px;
}

.zx-go-btn {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 11px 12px;
  border: 1px solid var(--zx-线深);
  border-radius: 3px;
  background: var(--zx-纸);
  color: var(--zx-墨);
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: border-color 0.15s ease, background 0.15s ease, transform 0.12s ease;
}

.zx-go-btn:hover:not(:disabled) {
  border-color: var(--zx-主);
  background: #fbf3e8;
}

.zx-go-btn:active:not(:disabled) {
  transform: translateY(1px);
}

.zx-go-btn:disabled {
  opacity: 0.5;
  cursor: default;
}

.zx-go-name {
  font-size: 13.5px;
  font-weight: 600;
  letter-spacing: 0.03em;
}

.zx-go-when {
  font-size: 10.5px;
  color: var(--zx-墨淡);
}

.zx-after {
  margin-top: 12px;
  padding-top: 11px;
  border-top: 1px solid var(--zx-线);
}

.zx-after .zx-btn {
  margin-top: 8px;
}

.zx-did {
  margin: 10px 0 0;
  padding: 7px 11px;
  border-left: 2px solid var(--zx-绿);
  background: #f2f6f1;
  font-size: 12px;
  color: #41603f;
  word-break: break-word;
}

.zx-receipt {
  margin: 0 0 11px;
  padding: 7px 11px;
  border-left: 2px solid var(--zx-绿);
  background: #f2f6f1;
  font-size: 12px;
  color: #41603f;
}

.zx-site {
  margin-bottom: 10px;
  border: 1px solid var(--zx-线);
  border-radius: 3px;
  overflow: hidden;
}

.zx-site-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  padding: 7px 12px;
  background: var(--zx-纸深);
  border-bottom: 1px solid var(--zx-线);
}

.zx-site-name {
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.03em;
}

.zx-site-tag {
  font-size: 11px;
  color: var(--zx-墨淡);
  font-variant-numeric: tabular-nums;
}

.zx-job {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  background: var(--zx-纸);
}

.zx-job + .zx-job {
  border-top: 1px dashed var(--zx-线);
}

.zx-job-main {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
  flex: 1;
}

.zx-job-name {
  font-size: 13px;
  font-weight: 600;
}

.zx-job-desc {
  font-size: 11.5px;
  color: var(--zx-墨淡);
}

.zx-job-meta {
  font-size: 11px;
  color: var(--zx-主);
  font-variant-numeric: tabular-nums;
}

.zx-site-lock {
  margin: 0;
  padding: 8px 12px;
  border-top: 1px dashed var(--zx-线);
  background: var(--zx-纸);
  font-size: 11px;
  color: var(--zx-墨淡);
}
