.zx-panel{--zx-纸: #fbf7ef;--zx-纸深: #f4ede0;--zx-线: #e0d5c2;--zx-线深: #cdbfa6;--zx-墨: #3b332a;--zx-墨淡: #8a7a66;--zx-主: #9c6b3c;--zx-主淡: #c69a63;--zx-绿: #5c7a5f;--zx-红: #a35b4e;--zx-蓝: #5b6f86;box-sizing:border-box;width:100%;max-width:100%;padding:0;border:1px solid var(--zx-线);border-radius:4px;background:var(--zx-纸);color:var(--zx-墨);font-family:"PingFang SC","Noto Sans SC","Microsoft YaHei",sans-serif;font-size:13px;line-height:1.6;text-align:left;overflow:hidden;box-shadow:0 1px 0 rgba(0,0,0,.03),0 6px 18px -12px rgba(80,60,30,.5)}.zx-panel *{box-sizing:border-box}.zx-top{display:flex;align-items:flex-end;justify-content:space-between;gap:12px;padding:11px 14px 10px;background:linear-gradient(180deg, var(--zx-纸深), var(--zx-纸));border-bottom:1px solid var(--zx-线)}.zx-clock{display:flex;align-items:baseline;gap:8px;min-width:0}.zx-clock-date{font-size:11.5px;color:var(--zx-墨淡);letter-spacing:.02em}.zx-clock-time{font-size:19px;font-weight:600;font-variant-numeric:tabular-nums;letter-spacing:.02em;color:var(--zx-墨)}.zx-top-right{display:flex;align-items:baseline;gap:14px;text-align:right}.zx-money{font-size:18px;font-weight:700;color:var(--zx-主);font-variant-numeric:tabular-nums}.zx-money-unit{font-size:11px;font-weight:400;color:var(--zx-墨淡);margin-left:2px}.zx-when{font-size:11.5px;color:var(--zx-墨淡);line-height:1.35;font-variant-numeric:tabular-nums}.zx-stats{display:grid;grid-template-columns:repeat(4, minmax(0, 1fr));gap:1px;background:var(--zx-线);border-bottom:1px solid var(--zx-线)}.zx-stat{padding:9px 12px 10px;background:var(--zx-纸);min-width:0}.zx-stat-top{display:flex;align-items:baseline;justify-content:space-between;gap:6px}.zx-stat-name{font-size:11px;color:var(--zx-墨淡);letter-spacing:.06em}.zx-stat-val{font-size:14px;font-weight:600;font-variant-numeric:tabular-nums;color:var(--zx-墨)}.zx-bar{height:4px;margin-top:5px;background:var(--zx-纸深);border-radius:2px;overflow:hidden}.zx-bar-in{height:100%;border-radius:2px;transition:width .35s ease}.zx-bar-饥饿 .zx-bar-in{background:linear-gradient(90deg, var(--zx-主淡), var(--zx-主))}.zx-bar-心情 .zx-bar-in{background:linear-gradient(90deg, #c98fae, #a4708f)}.zx-bar-健康 .zx-bar-in{background:linear-gradient(90deg, #8cae8f, var(--zx-绿))}.zx-bar-体力 .zx-bar-in{background:linear-gradient(90deg, #8fa3b8, var(--zx-蓝))}.zx-bar-体力.zx-bar-低 .zx-bar-in{background:linear-gradient(90deg, #c98f80, var(--zx-红))}.zx-tabs{display:flex;gap:4px;padding:9px 12px 0;background:var(--zx-纸)}.zx-tab{flex:1;padding:7px 4px;border:1px solid rgba(0,0,0,0);border-bottom:none;border-radius:3px 3px 0 0;background:rgba(0,0,0,0);color:var(--zx-墨淡);font:inherit;font-size:12.5px;letter-spacing:.04em;cursor:pointer;transition:color .15s ease,background .15s ease}.zx-tab:hover{color:var(--zx-墨);background:var(--zx-纸深)}.zx-tab-on{border-color:var(--zx-线);background:#fff;color:var(--zx-墨);font-weight:600}.zx-body{padding:12px 14px 14px;background:#fff;border-top:1px solid var(--zx-线);min-height:120px}.zx-hint{margin:0 0 10px;font-size:11.5px;color:var(--zx-墨淡)}.zx-note{padding:9px 11px;border-left:2px solid var(--zx-主淡);background:var(--zx-纸深);font-size:12px;color:var(--zx-墨)}.zx-note-淡{border-left-color:var(--zx-线深);color:var(--zx-墨淡);background:rgba(0,0,0,0);padding:8px 0 0}.zx-btn{padding:6px 13px;border:1px solid var(--zx-线深);border-radius:3px;background:var(--zx-纸深);color:var(--zx-墨);font:inherit;font-size:12px;cursor:pointer;transition:background .15s ease,border-color .15s ease}.zx-btn:hover:not(:disabled){border-color:var(--zx-主);background:#f0e2cd}.zx-btn:disabled{border-color:var(--zx-线);background:#f7f3ea;color:#a89c8b;cursor:default}.zx-btn-主{border-color:var(--zx-主);background:var(--zx-主);color:#fff8ee}.zx-btn-主:hover:not(:disabled){background:#8a5d33}.zx-空{padding:14px 0;font-size:12px;color:var(--zx-墨淡);text-align:center}@media(max-width: 560px){.zx-top{flex-direction:column;align-items:flex-start;gap:4px}.zx-top-right{text-align:left;gap:12px}.zx-stats{grid-template-columns:repeat(2, minmax(0, 1fr))}.zx-body{padding:10px 11px 12px}}