
@use './面板样式.scss';

/* 二级导航：一层是四个店，进店以后只看这一类的货。 */
.zx-shop-nav {
  display: flex;
  gap: 1px;
  border: 1px solid var(--zx-线);
  border-radius: 3px;
  overflow: hidden;
  background: var(--zx-线);
}

.zx-nav-item {
  flex: 1;
  padding: 7px 4px;
  border: none;
  background: var(--zx-纸深);
  color: var(--zx-墨淡);
  font: inherit;
  font-size: 12px;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
}

.zx-nav-item:hover {
  color: var(--zx-墨);
}

.zx-nav-on {
  background: #fff;
  color: var(--zx-墨);
  font-weight: 600;
}

.zx-nav-n {
  margin-left: 3px;
  font-size: 10.5px;
  color: var(--zx-墨淡);
  font-variant-numeric: tabular-nums;
}

.zx-buy {
  margin: 0 0 9px;
  padding: 6px 10px;
  border-left: 2px solid var(--zx-绿);
  background: #f2f6f1;
  font-size: 12px;
  color: #41603f;
}

/* 货架：窄卡两列，宽了自动变三列。一张卡只放名字、一句说明、价钱和一个动作。 */
.zx-goods {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(210px, 1fr));
  gap: 8px;
}

.zx-good {
  display: flex;
  flex-direction: column;
  padding: 9px 11px 10px;
  border: 1px solid var(--zx-线);
  border-radius: 3px;
  background: var(--zx-纸);
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.zx-good:hover {
  border-color: var(--zx-线深);
  box-shadow: 0 4px 12px -10px rgba(80, 60, 30, 0.8);
}

.zx-good-top {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}

.zx-good-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--zx-墨);
}

.zx-good-have {
  flex-shrink: 0;
  font-size: 10.5px;
  color: var(--zx-主);
  font-variant-numeric: tabular-nums;
}

.zx-good-note {
  margin: 3px 0 8px;
  font-size: 11px;
  line-height: 1.45;
  color: var(--zx-墨淡);
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.zx-good-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-top: auto;
  padding-top: 7px;
  border-top: 1px dashed var(--zx-线);
}

.zx-good-price {
  font-size: 15px;
  font-weight: 600;
  color: var(--zx-主);
  font-variant-numeric: tabular-nums;
}

.zx-unit {
  margin-left: 1px;
  font-size: 10.5px;
  font-weight: 400;
  color: var(--zx-墨淡);
}
