.zx-game-body{min-width:0}.zx-ask{margin:0 0 12px;font-size:13.5px;font-weight:600;color:var(--zx-墨);line-height:1.5}.zx-ask-tag{display:inline-block;margin-right:7px;padding:1px 7px;border:1px solid var(--zx-线深);border-radius:2px;font-size:10.5px;font-weight:400;color:var(--zx-墨淡);letter-spacing:.04em;vertical-align:1px}.zx-opts{display:grid;gap:7px}.zx-opts-row{grid-template-columns:repeat(2, minmax(0, 1fr))}.zx-opts-4{grid-template-columns:repeat(4, minmax(0, 1fr))}.zx-opt{padding:11px 13px;border:1px solid var(--zx-线深);border-radius:3px;background:#fff;color:var(--zx-墨);font:inherit;font-size:12.5px;text-align:left;cursor:pointer;transition:border-color .12s ease,background .12s ease,transform .12s ease}.zx-opt:hover{border-color:var(--zx-主);background:#fbf3e8}.zx-opt:active{transform:translateY(1px);background:#f4e7d4}.zx-opt-num{display:block;margin-top:2px;font-size:11px;color:var(--zx-墨淡);font-variant-numeric:tabular-nums}@media(max-width: 560px){.zx-opts-4{grid-template-columns:repeat(2, minmax(0, 1fr))}}