
@use '../面板样式.scss';

/* 小游戏是一块介入感更强的卡：底色比货架深一点，边框粗一点，跟面板的其他部分分得开。 */
.zx-frame {
  margin-top: 12px;
  border: 1px solid var(--zx-线深);
  border-radius: 3px;
  background: linear-gradient(180deg, #f7efe1, #fdfaf4);
  overflow: hidden;
}

.zx-frame-head {
  display: flex;
  align-items: baseline;
  gap: 12px;
  padding: 9px 12px 0;
  font-size: 11.5px;
  color: var(--zx-墨淡);
}

.zx-frame-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--zx-墨);
  letter-spacing: 0.03em;
}

.zx-frame-prog,
.zx-frame-time {
  font-variant-numeric: tabular-nums;
}

.zx-frame-time {
  color: var(--zx-主);
  font-weight: 600;
}

.zx-frame-quit {
  margin-left: auto;
  padding: 2px 10px;
  border: 1px solid var(--zx-线深);
  border-radius: 3px;
  background: transparent;
  color: var(--zx-墨淡);
  font: inherit;
  font-size: 11px;
  cursor: pointer;
}

.zx-frame-quit:hover {
  border-color: var(--zx-主);
  color: var(--zx-墨);
}

.zx-frame-bar {
  height: 3px;
  margin: 7px 12px 0;
  border-radius: 2px;
  background: #e8ddc9;
  overflow: hidden;
}

.zx-frame-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--zx-主淡), var(--zx-主));
  transition: width 1s linear;
}

.zx-frame-body {
  padding: 12px;
}

.zx-frame-tip {
  margin: 0;
  padding: 8px 12px 10px;
  border-top: 1px dashed var(--zx-线);
  font-size: 11.5px;
  color: #41603f;
}

.zx-frame-tip-静 {
  color: var(--zx-墨淡);
}
