
@use './面板样式.scss';

.zx-sis-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--zx-线);
}

.zx-sis-id {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.zx-sis-name {
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.04em;
}

.zx-sis-age {
  font-size: 11.5px;
  color: var(--zx-墨淡);
}

.zx-sis-line {
  font-size: 11.5px;
  color: var(--zx-墨淡);
  text-align: right;
}

.zx-ill {
  margin: 10px 0 0;
  padding: 7px 11px;
  border-left: 2px solid var(--zx-红);
  background: #faf1ef;
  font-size: 12px;
  color: #7d4438;
}

.zx-did {
  margin: 10px 0 0;
  padding: 7px 11px;
  border-left: 2px solid var(--zx-绿);
  background: #f2f6f1;
  font-size: 12px;
  color: #41603f;
}

.zx-sec {
  margin-top: 14px;
}

.zx-sec-head {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--zx-线);
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: 0.03em;
}

.zx-sec-sub {
  font-size: 10.5px;
  font-weight: 400;
  color: var(--zx-墨淡);
}

.zx-tiles {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 7px;
  margin-top: 8px;
}

.zx-tile {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 8px 11px;
  border: 1px solid var(--zx-线);
  border-radius: 3px;
  background: var(--zx-纸);
  color: var(--zx-墨);
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: border-color 0.15s ease, background 0.15s ease;
}

.zx-tile:hover:not(:disabled) {
  border-color: var(--zx-主);
  background: #fbf3e8;
}

.zx-tile:disabled {
  opacity: 0.45;
  cursor: default;
}

.zx-tile-on {
  border-color: var(--zx-主);
  background: #f6ecdd;
}

.zx-tile-name {
  font-size: 12.5px;
}

.zx-tile-note {
  font-size: 10.5px;
  color: var(--zx-墨淡);
}
