
@use './面板样式.scss';

.zx-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(165px, 1fr));
  gap: 8px;
}

.zx-cell {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 9px 11px;
  border: 1px solid var(--zx-线);
  border-radius: 3px;
  background: var(--zx-纸);
}

.zx-cell-k {
  font-size: 10.5px;
  color: var(--zx-墨淡);
  letter-spacing: 0.05em;
}

.zx-cell-v {
  font-size: 14px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.zx-sec {
  margin-top: 14px;
}

.zx-sec-head {
  padding-bottom: 6px;
  border-bottom: 1px solid var(--zx-线);
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: 0.03em;
}

.zx-line {
  margin: 8px 0 0;
  font-size: 11.5px;
  line-height: 1.6;
}

.zx-dim {
  color: var(--zx-墨淡);
}

.zx-skills {
  margin-top: 8px;
}

.zx-skill {
  display: grid;
  grid-template-columns: 62px minmax(60px, 1fr) 48px auto;
  align-items: center;
  gap: 10px;
  padding: 6px 0;
  border-bottom: 1px dashed var(--zx-线);
  font-size: 12px;
}

.zx-skill-name {
  color: var(--zx-墨);
}

.zx-skill-track {
  height: 4px;
  background: var(--zx-纸深);
  border-radius: 2px;
  overflow: hidden;
}

.zx-skill-track i {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, var(--zx-主淡), var(--zx-主));
  border-radius: 2px;
}

.zx-skill-val {
  font-weight: 600;
  color: var(--zx-主);
}

.zx-skill-times {
  font-size: 11px;
  color: var(--zx-墨淡);
  font-variant-numeric: tabular-nums;
}

@media (max-width: 560px) {
  .zx-skill {
    grid-template-columns: 56px minmax(40px, 1fr) 44px;
  }
  .zx-skill-times {
    grid-column: 1 / -1;
    text-align: right;
  }
}
